function calSVG() {
  const pts = [[0, 0], [0.1, 0.28], [0.2, 0.56], [0.3, 0.83], [0.4, 1.11], [0.5, 1.39]];
  const L0 = 40, T = 12, pw = 300, ph = 160, X = c => (L0 + c / 0.5 * pw).toFixed(1), Y = a => (T + (1 - a / 1.5) * ph).toFixed(1);
  let s = `<svg viewBox="0 0 360 215" class="chart" role="img" aria-label="Calibration curve: absorbance against copper sulfate concentration, straight line A = 2.78c; an absorbance of 0.950 reads off as 0.34 mol per litre"><title>Colourimetry calibration curve</title>`;
  for (let i = 0; i <= 5; i++) { const x = L0 + i * pw / 5; s += `<line class="gl" x1="${x}" x2="${x}" y1="${T}" y2="${T + ph}"/><text class="tk" x="${x}" y="${T + ph + 13}" text-anchor="middle">${(i * 0.1).toFixed(1)}</text>`; }
  for (let j = 0; j <= 3; j++) { const y = T + j * ph / 3; s += `<line class="gl" x1="${L0}" x2="${L0 + pw}" y1="${y}" y2="${y}"/><text class="tk" x="${L0 - 5}" y="${y + 3.5}" text-anchor="end">${(1.5 - j * 0.5).toFixed(1)}</text>`; }
  s += `<line class="ax" x1="${L0}" x2="${L0}" y1="${T}" y2="${T + ph}"/><line class="ax" x1="${L0}" x2="${L0 + pw}" y1="${T + ph}" y2="${T + ph}"/>`;
  s += `<line x1="${X(0)}" y1="${Y(0)}" x2="${X(0.5)}" y2="${Y(1.39)}" style="stroke:var(--accent);stroke-width:2.2"/>`;
  pts.forEach(p => { s += `<circle cx="${X(p[0])}" cy="${Y(p[1])}" r="3.5" class="mk"/>`; });
  s += `<line class="guide" x1="${L0}" x2="${X(0.342)}" y1="${Y(0.95)}" y2="${Y(0.95)}"/><line class="guide" x1="${X(0.342)}" x2="${X(0.342)}" y1="${Y(0.95)}" y2="${T + ph}"/>`;
  s += `<text class="lbl" x="${L0 + 4}" y="${+Y(0.95) - 4}">A = 0.950</text><text class="lbl" x="${+X(0.342) + 4}" y="${T + ph - 6}">0.34 M</text>`;
  s += `<text class="axl" x="${L0 + pw / 2}" y="210" text-anchor="middle">[CuSO₄] (mol L⁻¹)</text><text class="axl" transform="translate(11 ${T + ph / 2}) rotate(-90)" text-anchor="middle">Absorbance (635 nm)</text></svg>`;
  return `<div class="viz">${s}<p class="viz-cap">Line of best fit: A = 2.78 × [CuSO₄].</p></div>`;
}
const box = (t, k = '') => `<div style="border:1.5px solid ${k === 'fl-end' ? 'var(--accent)' : 'var(--line)'};background:${k === 'fl-soft' ? 'var(--surface-2)' : k === 'fl-end' ? 'var(--accent-soft)' : 'var(--surface)'};border-radius:8px;padding:6px 10px;margin:6px 0;font-size:.88rem">${t}</div>`;
const M8_VIZ = {
  m8flame: () => tbl(['Cation', 'Flame colour'], [['Ba²⁺', '(pale) apple green'], ['Ca²⁺', 'reddish brown (or orange-red)'], ['Mg²⁺', 'colourless'], ['Pb²⁺', 'blue-grey'], ['Ag⁺', 'colourless'], ['Cu²⁺', 'blue-green (white flashes)'], ['Na⁺', 'orange-yellow'], ['Fe²⁺', 'gold (very hot), blue-green to orange-brown'], ['Fe³⁺', 'orange-brown']],
    'Just a guide: people see colours differently, and some ions need a hotter flame than a Bunsen gives.'),
  m8ppt: () => tbl(['Cation', 'Solution colour', 'with SO₄²⁻', 'with OH⁻', 'with CO₃²⁻'], [['Ca²⁺', 'colourless', 'white', 'white', 'white'], ['Ag⁺', 'colourless', 'white', 'brown', 'yellow'], ['Fe²⁺', 'pale green', 'no precipitate', 'green', 'green'], ['Fe³⁺', 'orange-brown', 'no precipitate', 'brown', 'brown'], ['Cu²⁺', 'blue', 'no precipitate', 'blue', 'green']]),
  m8anion: () => `<div class="viz"><div>${box('<b>Test 1:</b> add AgNO₃(aq)')}</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><div>${box('No precipitate: NO₃⁻ or SO₄²⁻', 'fl-soft')}${box('<b>Test 2:</b> add BaCl₂ to a fresh sample')}${box('No precipitate → <b>NO₃⁻</b><br>White precipitate → <b>SO₄²⁻</b>', 'fl-end')}</div>
    <div>${box('Precipitate: Cl⁻, Br⁻, I⁻, S²⁻, CO₃²⁻ or PO₄³⁻', 'fl-soft')}${box('<b>Test 2:</b> add dilute HNO₃ to the precipitate')}${box('Stays: white <b>Cl⁻</b>, cream <b>Br⁻</b>, yellow <b>I⁻</b>, black <b>S²⁻</b>', 'fl-end')}${box('Dissolves: white <b>CO₃²⁻</b>, yellow <b>PO₄³⁻</b>', 'fl-end')}</div></div></div>`,
  m8cal: calSVG
};

